import{_ as c,C as h,o,c as i,j as t,a,E as r,a2 as g}from"./chunks/framework.CQjSGuJt.js";const b=JSON.parse('{"title":"3. Rules & mechanics","description":"","frontmatter":{},"headers":[],"relativePath":"gdd/rules.md","filePath":"gdd/rules.md"}'),d={name:"gdd/rules.md"};function l(s,n,u,m,p,x){const e=h("Badge");return o(),i("div",null,[n[0]||(n[0]=t("h1",{id:"_3-rules-mechanics",tabindex:"-1"},[a("3. Rules & mechanics "),t("a",{class:"header-anchor",href:"#_3-rules-mechanics","aria-label":'Permalink to "3. Rules & mechanics"'},"​")],-1)),r(e,{type:"tip",text:"Live"}),n[1]||(n[1]=g(' Luật dưới đây lấy từ đặc tả bản gốc Fish Bus (<code>GAME_SPEC.md</code> v1); đã có trong code Phaser (<code>src/core/</code>).<h2 id="_3-1-thang" tabindex="-1">3.1 Thắng <a class="header-anchor" href="#_3-1-thang" aria-label="Permalink to &quot;3.1 Thắng&quot;">​</a></h2><p>Ống rỗng, không còn hàng chờ, và <strong>mọi xe đều đã ✓ hoặc rỗng</strong>. (<code>goal</code> = số xe hoàn thành khi thắng, editor tính bằng solver; không hiện trên HUD. Bộ đếm trên HUD là số nấc trên ống, xem <a href="./core-loop">Core loop</a>.)</p><h2 id="_3-2-thua-ket" tabindex="-1">3.2 Thua (kẹt) <a class="header-anchor" href="#_3-2-thua-ket" aria-label="Permalink to &quot;3.2 Thua (kẹt)&quot;">​</a></h2><p>Đồng thời thoả mãn:</p><ul><li>Không có xe nào <strong>tap được có hiệu quả</strong> (ống không còn chỗ hoặc mọi xe đều ✓/rỗng), và</li><li>Không có hàng chờ xả, và</li><li>Trong <strong>1 vòng ống</strong> (<code>L / pipeSpeed</code> giây) không có nấc nào vào xe.</li></ul><p>Khi đã qua 50% thời gian trên → bật cảnh báo (ống nhấp nháy đỏ). Có cá vào xe → reset bộ đếm. Khi thua: popup cho phép dùng booster để cứu hoặc chơi lại.</p><h2 id="_3-3-booster" tabindex="-1">3.3 Booster <a class="header-anchor" href="#_3-3-booster" aria-label="Permalink to &quot;3.3 Booster&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Booster</th><th>Tác dụng</th></tr></thead><tbody><tr><td><strong>Return</strong> (nút mũi tên vòng, trường <code>undo</code>)</td><td>Lấy <strong>nấc vừa vào xe gần nhất</strong> (toàn màn) đưa bay thẳng về đúng vị trí cũ ở xe nó đã rời. Chỉ dùng được khi: nấc vẫn còn ở đuôi xe đích; ở xe cũ, chỗ cũ đúng là chỗ trống kế tiếp (nấc ngay dưới chưa bị chuyển đi, chưa nhận nấc khác), xe cũ chưa ✓ và không có hàng chờ. Không thoả → nút mờ, không dùng được (không lùi về nấc cũ hơn). Nếu nấc đó đã làm xe đích ✓ thì xe mở nắp lại.</td></tr><tr><td><strong>Shuffle</strong> (nút giữa)</td><td>Bấm nút → chọn 1 xe (xe chọn được sáng lên, xe khác mờ; bấm lại nút để huỷ). Các nấc trong xe được xếp lại: <strong>gom cùng màu thành cụm, cụm đông ở đầu xe, màu lẻ (ít nấc) ra đuôi</strong> để xả được ngay; các cụm bằng nhau xếp ngẫu nhiên (PRNG có seed). Không dùng cho xe ✓, xe rỗng, xe 1 màu, xe đang có hàng chờ, hoặc xe đã đúng thứ tự.</td></tr><tr><td><strong>Thêm xe</strong></td><td>Thêm 1 xe rỗng (capacity 4) vào vị trí dự phòng <code>spareSlots</code> tiếp theo của level; tồn tại tới hết màn, chơi lại thì mất. Booster dùng được ở <strong>mọi level</strong>, nên level nào cũng có sẵn ít nhất 1 vị trí dự phòng.</td></tr></tbody></table><h2 id="_3-4-xem-loi-giai-tu-choi" tabindex="-1">3.4 Xem lời giải (tự chơi) <a class="header-anchor" href="#_3-4-xem-loi-giai-tu-choi" aria-label="Permalink to &quot;3.4 Xem lời giải (tự chơi)&quot;">​</a></h2><p>Trong Cài đặt có nút <strong>Xem lời giải</strong>: chơi lại màn, solver tìm lời giải ngắn về thời gian (ưu tiên các nhánh ít thời gian + ít nấc còn phải xếp, bước chờ chỉ chờ tới khi có nấc vào xe) rồi <strong>bàn tay hướng dẫn</strong> bay tới từng xe và ấn xuống đúng lúc tap (lịch tap dựng từ lời giải, mô phỏng giống hệt nên chắc chắn thắng). Chạm vào bàn chơi để dừng; người chơi chơi tiếp từ trạng thái lúc dừng. Dùng để thử màn và sau này cho tutorial.</p><h2 id="_3-5-mo-phong" tabindex="-1">3.5 Mô phỏng <a class="header-anchor" href="#_3-5-mo-phong" aria-label="Permalink to &quot;3.5 Mô phỏng&quot;">​</a></h2><ul><li>Bước cố định <strong>60 Hz</strong>, độc lập khung hình → cùng level + cùng chuỗi thao tác = cùng kết quả (dùng cho solver, replay, undo).</li><li>Băng chuyền: <code>offset += pipeSpeed * dt</code>; vị trí ô <code>i</code> = <code>(i * S + offset) mod L</code> với <code>S = L / C</code>.</li><li>Random duy nhất (Shuffle, khi các cụm bằng nhau) dùng PRNG có seed.</li></ul>',17))])}const _=c(d,[["render",l]]);export{b as __pageData,_ as default};
